    width: 150px !important;
    height: 49px !important;
    background-color: #383838 !important;
    color: #ffffff !important;
    font-family: 'Jost', sans-serif !important;
    font-weight: 500 !important;
    font-size: 17px !important;
    border: none !important;
    border-radius:7px !important;
    cursor: pointer !important;
    letter-spacing: 1px !important;
}

/* Remove hover animation */
.fierro-subscribe .wpcf7 input[type="submit"]:hover {
    background-color: #383838 !important;
    transform: none !important;
    transition: none !important;
}

/* Remove CF7 default red border on focus */
.fierro-subscribe .wpcf7 input[type="email"]:focus {
    border: 1px solid #383838 !important;
    outline: none !important;
    box-shadow: none !important;
}

/* Remove CF7 validation error styling */
.fierro-subscribe .wpcf7 .wpcf7-not-valid {
    border: 1px solid #383838 !important;
}

/* Hide CF7 validation message if needed */
.fierro-subscribe .wpcf7 .wpcf7-not-valid-tip {
    display: none !important;
}


/* Mobile - Reduce email field width */
@media (max-width: 767px) {
    .fierro-subscribe .wpcf7 input[type="email"] {
        width: 100% !important;
        font-size: 9px;
    }
    .fierro-subscribe .wpcf7 input[type="submit"] {
        width: 100% !important;
    }
    /* Stack field and button vertically on mobile */
    .fierro-subscribe .wpcf7 form {
        flex-direction: column !important;
        width: 100% !important;
    }
    .fierro-subscribe .wpcf7 .wpcf7-form-control-wrap {
        width: 100% !important;
    }
}
